            for (int i = 0; i < n; i++) {
                arr[i] = sc.nextInt();
            }
            Arrays.sort(arr);
            int count = 0;
            int sum = 0;
            for (int i = 0; i < n; i++) {
                if (arr[i] > 0) {
                    count++;
                    sum += arr[i];
                }
            }
            if (count == 0) {
                System.out.println(0);
            } else {
                System.out.println(sum / count);
            }
        }
    }
